"""Portable experiment reports generated entirely from persisted run evidence."""
import csv
import io
import json
from html import escape


def csv_report(detail):
    output=io.StringIO();writer=csv.writer(output)
    writer.writerow(['position','event_id','source','label','expected_alert','observed_alerts','classification','expected_techniques','observed_techniques','latency_ms'])
    for row in detail['events']:
        writer.writerow([row['position'],row['event_id'],row['source'],row['label'],row['expected_positive'],len(row['alerts']),row['classification'],','.join(row['expected_techniques']),','.join(row['observed_techniques']),row['latency_ms']])
    return output.getvalue()


def html_report(detail):
    metrics=detail['metrics'] or {}
    def pct(value): return f'{value*100:.1f}%' if value is not None else 'N/A'
    rows=''.join(f"<tr><td>{escape(row['label'])}</td><td>{escape(row['source'])}</td><td>{row['classification'].upper()}</td><td>{len(row['alerts'])}</td><td>{escape(', '.join(row['expected_techniques']) or 'None')}</td><td>{escape(', '.join(row['observed_techniques']) or 'None')}</td></tr>" for row in detail['events'])
    coverage=''.join(f"<tr><td>{escape(item['technique'])}</td><td>{escape(item['name'])}</td><td>{escape(item['status'])}</td></tr>" for item in metrics.get('coverage',[]))
    trace=''.join(f"<li><strong>{escape(item['stage'].upper())}</strong> — {escape(item['message'])}<small>{escape(item['recorded_at'])}</small></li>" for item in detail['traces'])
    order=['client','web','db','identity']
    nodes=sorted(detail['topology']['nodes'],key=lambda node: order.index(node['id']) if node['id'] in order else len(order));positions={node['id']:(100+i*180,90) for i,node in enumerate(nodes)}
    lines=''.join(f'<line x1="{positions[edge["source"]][0]+24}" y1="90" x2="{positions[edge["target"]][0]-24}" y2="90" stroke="{"#b65c4f" if edge["blocked"] else "#7c93aa"}" stroke-dasharray="{"5 4" if edge["blocked"] else "0"}" marker-end="url(#report-arrow)"/>' for edge in detail['topology']['edges'])
    circles=''.join(f'''<g><circle cx="{positions[node["id"]][0]}" cy="90" r="24" fill="#f5e9ca" stroke="#aa8648"/><text x="{positions[node["id"]][0]}" y="140" text-anchor="middle" font-size="11">{escape(node["name"])}</text><text x="{positions[node["id"]][0]}" y="160" text-anchor="middle" font-size="10">{escape('blocked ports: '+', '.join(map(str,node.get('blocked_ports',[]))) if node.get('blocked_ports') else node['state'])}</text></g>''' for node in nodes)
    return f'''<!doctype html><html><head><meta charset="utf-8"><title>TwinTrace Lab — {escape(detail['name'])}</title><style>body{{font:14px system-ui;max-width:1100px;margin:40px auto;padding:0 24px;color:#203044;line-height:1.7}}h1{{font-size:32px}}h2{{margin-top:36px}}.scope{{border-left:4px solid #ba9558;padding:12px 18px;background:#fbf6eb}}.metrics{{display:flex;gap:24px;flex-wrap:wrap;margin:25px 0}}.metrics b{{font-size:24px;display:block}}table{{border-collapse:collapse;width:100%;font-size:12px}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #dce2e8}}small{{display:block;color:#6a7a8e}}li{{padding:7px 0}}svg{{width:100%;max-height:200px}}@media print{{body{{margin:0;max-width:none}}h2{{break-after:avoid}}tr{{break-inside:avoid}}}}</style></head><body><p>TWINTRACE LAB / EXPERIMENT REPORT</p><h1>{escape(detail['name'])}</h1><p class="scope">Synthetic replay only. Response actions and model verification are simulated. No real attacks or containment commands were executed.</p><p>Run: {escape(detail['run_id'])} · Seed: {detail['seed']} · Scenario version: {detail['snapshot']['version']} · State: {escape(detail['status'])}</p><p>Created: {escape(detail['created_at'])} · Completed: {escape(detail['completed_at'] or 'Pending')}</p><div class="metrics"><div><b>{pct(metrics.get('precision'))}</b>Precision</div><div><b>{pct(metrics.get('recall'))}</b>Recall</div><div><b>{pct(metrics.get('f1'))}</b>F1</div><div><b>{metrics.get('mean_detection_ms') if metrics.get('mean_detection_ms') is not None else 'N/A'}</b>Mean processing latency (ms)</div></div><p>TP {metrics.get('tp',0)} · FP {metrics.get('fp',0)} · FN {metrics.get('fn',0)} · TN {metrics.get('tn',0)}</p><h2>Scenario & methodology</h2><p>{escape(detail['snapshot']['description'])}</p><p>{escape(metrics.get('methodology','Evaluation pending.'))}</p><p>{escape(detail['reproducibility'])}</p><h2>Detection configuration</h2><pre>{escape(json.dumps(detail['snapshot'].get('detection_config'),indent=2)) if detail['snapshot'].get('detection_config') else 'Legacy run: original detector settings were not captured.'}</pre><h2>Run-local digital twin</h2><svg viewBox="0 0 780 190" role="img" aria-label="Scenario topology and simulated state"><defs><marker id="report-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#7c93aa"/></marker></defs>{lines}{circles}</svg><small>Dashed red links are blocked in the simulation model.</small><p>{escape(detail['topology']['provenance'])}</p><h2>Ground truth vs observed evidence</h2><table><thead><tr><th>Observation</th><th>Source</th><th>Class</th><th>Alerts</th><th>Expected techniques</th><th>Observed techniques</th></tr></thead><tbody>{rows}</tbody></table><h2>ATT&CK coverage</h2><table><thead><tr><th>ID</th><th>Technique</th><th>Outcome</th></tr></thead><tbody>{coverage}</tbody></table><h2>Simulated verification</h2><pre>{escape(json.dumps(detail['verification'],indent=2))}</pre><h2>Recorded process chain</h2><ol>{trace}</ol><h2>Limits</h2><p>Fixture labels are synthetic ground truth. Upstream alerts are source assertions, not independent proof of intrusion. Network reachability does not establish exploitability. These results are not a production benchmark. Real containment performed: false.</p><p>Print this document to save a PDF, or keep the JSON/CSV exports for reproducibility.</p></body></html>'''
